// seed: tests/seed.spec.ts (гость) · прод, только чтение (не-GET обрываются, SW заблокирован).
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, captureCatalog, openPage, openFilter, fields, enter, applyFilter, idsInRange, expectResults, EnterMode, LOAD,
} from './search-filters.helpers';

test.use({ serviceWorkers: 'block' });

const MIN = 1_000_000;
const MAX = 3_000_000;
const VARIANTS: { mode: EnterMode; order: 'мин→макс' | 'макс→мин' }[] = [
  { mode: 'type', order: 'мин→макс' },
  { mode: 'fill', order: 'мин→макс' },
  { mode: 'type', order: 'макс→мин' },
  { mode: 'fill', order: 'макс→мин' },
];

test.describe('Фильтры поиска — поля мин/макс, десктоп /search', () => {
  for (const v of VARIANTS) {
    test(`Поля «מינימום»/«מקסימום» (${v.mode === 'type' ? 'по цифре' : 'вставкой'}, ${v.order}): значения сохраняются, URL и выдача по диапазону #b4b8c9 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      const catalog = captureCatalog(page);
      await openPage(page, '/search');
      const expected = idsInRange(await catalog(), MIN, MAX);
      expect(expected.length, `в каталоге есть объявления ${MIN}–${MAX} — иначе данные сайта, не баг`).toBeGreaterThan(0);

      const scope = await openFilter(page, false);
      const f = fields(scope);
      const seq = v.order === 'мин→макс' ? [[f.min, MIN], [f.max, MAX]] as const : [[f.max, MAX], [f.min, MIN]] as const;
      await enter(seq[0][0], seq[0][1], v.mode);
      await enter(seq[1][0], seq[1][1], v.mode);
      await expect(f.min, 'после ввода второго поля первое не стёрлось').toHaveValue(String(MIN));
      await expect(f.max).toHaveValue(String(MAX));

      await applyFilter(page);
      await page.waitForURL(
        (u) => u.searchParams.get('minPrice') === String(MIN) && u.searchParams.get('maxPrice') === String(MAX),
        LOAD,
      );
      await expect(f.min, 'после «סנן תוצאות» мин на месте').toHaveValue(String(MIN));
      await expect(f.max, 'после «סנן תוצאות» макс на месте').toHaveValue(String(MAX));
      await expectResults(page, expected, `/search ${MIN}–${MAX}`);
    });
  }
});
